%% Figure 2: formal + physically informed consistency bounds
% Self-contained MATLAB script for the revised Golden-BV manuscript.
%
% The figure shows the branch-dependent correction
%   C_req = phi^(s*(2*alpha - 1)),  s = +1 or -1,
% together with:
%   (i)  the formal bound generated by 0 <= alpha <= 1, and
%   (ii) the illustrative physically informed range 0.3 <= alpha <= 0.7.
%
% Outputs:
%   Figure2_Golden_BV_consistency_bounds.png
%   Figure2_Golden_BV_consistency_bounds.pdf
%
% No external toolbox is required.

clear;
close all;
clc;

%% 1. User-adjustable settings
alphaPhysicalLow  = 0.30;
alphaPhysicalHigh = 0.70;

nAlpha = 1001;
alpha = linspace(0,1,nAlpha);

savePNG = true;
savePDF = true;
saveSVG = true;

pngResolution = 600;

pngName = 'Figure02.png';
pdfName = 'Figure02.pdf';
svgName = 'Figure02.svg';
%% 2. Golden-ratio constants and exact correction curves
phi = (1 + sqrt(5))/2;

% Positive-overpotential branch, s = +1:
CreqPlus = phi.^(2.*alpha - 1);

% Negative-overpotential branch, s = -1:
CreqMinus = phi.^(1 - 2.*alpha);

% Broad formal interval from 0 <= alpha <= 1.
CformalLow  = 1/phi;
CformalHigh = phi;

% Physically informed correction interval corresponding to the stated
% alpha range. This implementation remains correct if the chosen interval
% is not perfectly symmetric around alpha = 0.5.
physicalCandidates = [ ...
    phi^( 2*alphaPhysicalLow  - 1), ...
    phi^( 2*alphaPhysicalHigh - 1), ...
    phi^(-2*alphaPhysicalLow  + 1), ...
    phi^(-2*alphaPhysicalHigh + 1)  ...
    ];

CphysicalLow  = min(physicalCandidates);
CphysicalHigh = max(physicalCandidates);

%% 3. Numerical self-checks, including boundary cases
tol = 1e-12;

% alpha = 0
assert(abs(phi^(2*0 - 1) - CformalLow) < tol);
assert(abs(phi^(1 - 2*0) - CformalHigh) < tol);

% alpha = 0.5
assert(abs(phi^(2*0.5 - 1) - 1) < tol);
assert(abs(phi^(1 - 2*0.5) - 1) < tol);

% alpha = 1
assert(abs(phi^(2*1 - 1) - CformalHigh) < tol);
assert(abs(phi^(1 - 2*1) - CformalLow) < tol);

% The two branch corrections must remain reciprocal.
assert(max(abs(CreqPlus.*CreqMinus - 1)) < 1e-11);

% The full curves must remain inside the broad formal bounds.
assert(min(CreqPlus)  >= CformalLow  - tol);
assert(max(CreqPlus)  <= CformalHigh + tol);
assert(min(CreqMinus) >= CformalLow  - tol);
assert(max(CreqMinus) <= CformalHigh + tol);

% The illustrative physical interval must be nested in the formal interval.
assert(CphysicalLow  >= CformalLow  - tol);
assert(CphysicalHigh <= CformalHigh + tol);

% Inverse check: recover alpha from the positive-branch C_req values.
alphaRecovered = 0.5.*(1 + log(CreqPlus)./log(phi));
assert(max(abs(alphaRecovered - alpha)) < 1e-11);

fprintf('\nFigure 2 consistency-bound checks passed.\n');
fprintf('phi                    = %.8f\n',phi);
fprintf('Formal C_req interval  = %.5f to %.5f\n', ...
    CformalLow,CformalHigh);
fprintf('Physical alpha range   = %.2f to %.2f\n', ...
    alphaPhysicalLow,alphaPhysicalHigh);
fprintf('Physical C_req interval= %.5f to %.5f\n\n', ...
    CphysicalLow,CphysicalHigh);

%% 4. Figure setup
fig = figure( ...
    'Color','w', ...
    'Units','centimeters', ...
    'Position',[2 2 15.2 10.4]);

ax = axes(fig);
hold(ax,'on');
box(ax,'on');

% Publication-oriented palette matching the revised manuscript figures.
formalColor   = [0.90 0.90 0.90];
physicalColor = [0.82 0.91 0.84];
plusColor     = [0.00 0.45 0.74];
minusColor    = [0.85 0.33 0.10];
guideColor    = [0.45 0.45 0.45];

xMin = 0;
xMax = 1;
yMin = 0.56;
yMax = 1.68;

xlim(ax,[xMin xMax]);
ylim(ax,[yMin yMax]);

%% 5. Shaded nested bounds
% Formal band: all C_req values allowed by 0 <= alpha <= 1.
hFormal = patch( ...
    ax, ...
    [xMin xMax xMax xMin], ...
    [CformalLow CformalLow CformalHigh CformalHigh], ...
    formalColor, ...
    'EdgeColor','none', ...
    'FaceAlpha',0.55);

% Physically informed nested band.
hPhysical = patch( ...
    ax, ...
    [xMin xMax xMax xMin], ...
    [CphysicalLow CphysicalLow CphysicalHigh CphysicalHigh], ...
    physicalColor, ...
    'EdgeColor','none', ...
    'FaceAlpha',0.78);

%% 6. Reference lines
% C_req = 1 is the symmetric alpha = 0.5 current-amplitude condition.
plot(ax,[xMin xMax],[1 1],':', ...
    'Color',guideColor, ...
    'LineWidth',1.1, ...
    'HandleVisibility','off');

% Boundaries of the illustrative alpha prior.
plot(ax,[alphaPhysicalLow alphaPhysicalLow],[yMin yMax],':', ...
    'Color',guideColor, ...
    'LineWidth',0.9, ...
    'HandleVisibility','off');

plot(ax,[alphaPhysicalHigh alphaPhysicalHigh],[yMin yMax],':', ...
    'Color',guideColor, ...
    'LineWidth',0.9, ...
    'HandleVisibility','off');

%% 7. Exact branch-dependent correction curves
hPlus = plot( ...
    ax,alpha,CreqPlus, ...
    '-', ...
    'Color',plusColor, ...
    'LineWidth',2.2);

hMinus = plot( ...
    ax,alpha,CreqMinus, ...
    '--', ...
    'Color',minusColor, ...
    'LineWidth',2.0);

% Mark the symmetric point.
plot(ax,0.5,1,'o', ...
    'MarkerSize',6.5, ...
    'MarkerFaceColor','w', ...
    'MarkerEdgeColor',guideColor, ...
    'LineWidth',1.1, ...
    'HandleVisibility','off');

%% 8. Labels and annotations
xlabel(ax,'Transfer coefficient, $a$', ...
    'Interpreter','latex');

ylabel(ax,'Required correction, $C_{\mathrm{req}}$', ...
    'Interpreter','latex');

set(ax, ...
    'FontName','Arial', ...
    'FontSize',10, ...
    'LineWidth',0.9, ...
    'TickDir','out', ...
    'TickLabelInterpreter','latex', ...
    'Layer','top');

xticks(ax,0:0.1:1);
yticks(ax,0.6:0.2:1.6);

grid(ax,'on');
ax.GridAlpha = 0.12;
ax.MinorGridAlpha = 0.06;

% Bound labels.
text(ax,0.965,CformalHigh-0.020, ...
    sprintf('$\\phi=%.3f$',CformalHigh), ...
    'Interpreter','latex', ...
    'HorizontalAlignment','right', ...
    'VerticalAlignment','top', ...
    'FontSize',9);

text(ax,0.965,CformalLow+0.018, ...
    sprintf('$\\phi^{-1}=%.3f$',CformalLow), ...
    'Interpreter','latex', ...
    'HorizontalAlignment','right', ...
    'VerticalAlignment','bottom', ...
    'FontSize',9);

text(ax,0.985,CphysicalHigh-0.012, ...
    sprintf('$%.3f$',CphysicalHigh), ...
    'Interpreter','latex', ...
    'HorizontalAlignment','right', ...
    'VerticalAlignment','top', ...
    'FontSize',8.5);

text(ax,0.985,CphysicalLow+0.012, ...
    sprintf('$%.3f$',CphysicalLow), ...
    'Interpreter','latex', ...
    'HorizontalAlignment','right', ...
    'VerticalAlignment','bottom', ...
    'FontSize',8.5);

text(ax,0.5,1.1,'$a=0.5,\;C_{\mathrm{req}}=1$', ...
    'Interpreter','latex', ...
    'HorizontalAlignment','center', ...
    'VerticalAlignment','bottom', ...
    'FontSize',8.8);

% Small labels for the prior boundaries.
text(ax,alphaPhysicalLow, yMin+0.018, ...
    sprintf('$a=%.1f$',alphaPhysicalLow), ...
    'Interpreter','latex', ...
    'HorizontalAlignment','left', ...
    'VerticalAlignment','bottom', ...
    'FontSize',8.3, ...
    'Rotation',90);

text(ax,alphaPhysicalHigh, yMin+0.018, ...
    sprintf('$a=%.1f$',alphaPhysicalHigh), ...
    'Interpreter','latex', ...
    'HorizontalAlignment','left', ...
    'VerticalAlignment','bottom', ...
    'FontSize',8.3, ...
    'Rotation',90);

%% 9. Legend
lgd=legend( ...
    ax, ...
    [hFormal hPhysical hPlus hMinus], ...
    { ...
    'Formal $0\leq a\leq1$', ...
    'Illustrative $0.3\leq a\leq0.7$', ...
    '$C_{\mathrm{req},+}=\phi^{2a-1}$', ...
    '$C_{\mathrm{req},-}=\phi^{1-2a}$' ...
    }, ...
    'Interpreter','latex', ...
    'Location','north', ...
    'FontSize',8.7, ...
    'Box','on');

%% 10. Export
drawnow;

fitLegendBox(lgd,26);

drawnow;

if savePNG
    if exist('exportgraphics','file') == 2
        exportgraphics(fig,pngName,'Resolution',pngResolution);
    else
        print(fig,pngName,'-dpng',sprintf('-r%d',pngResolution));
    end
end

if savePDF
    if exist('exportgraphics','file') == 2
        exportgraphics(fig,pdfName,'ContentType','vector');
    else
        print(fig,pdfName,'-dpdf','-painters');
    end
end

if saveSVG
    % exportgraphics 不支持 SVG，只能用 print -dsvg
    print(fig,svgName,'-dsvg','-painters');
end

fprintf('Saved figure files:\n');
if savePNG
    fprintf('  %s\n',pngName);
end
if savePDF
    fprintf('  %s\n',pdfName);
end
if saveSVG
    fprintf('  %s\n',svgName);
end


function fitLegendBox(lgd, extraWidthPt)
    % Prevent legend text from overflowing its border

    % Compact legend symbol column (R2024b+)
    if isprop(lgd,'IconColumnWidth')
        lgd.IconColumnWidth = 18;
    end

    drawnow;

    % Enlarge box while keeping its right edge fixed
    lgd.Units = 'points';
    pos = lgd.Position;

    pos(1) = pos(1) - extraWidthPt;
    pos(3) = pos(3) + extraWidthPt;

    lgd.Position = pos;
end
